interface.definition:
a!localVariables(
  local!askView: if(
    ri!positionTypeID = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3235974"(askId: ri!askID, returnCDT: true),
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3338676"(
      askId: ri!askID,
      returnCDT: true,
      isCompleted: true,
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
        startIndex: 1,
        batchSize: 1,
        sort: #"SYSTEM_SYSRULES_sortInfo"(field: "rotationalAskId")
      )
    )
  ),
  local!rotationalASKDetails: if(
    ri!positionTypeID = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3127143"(
      askId: index(local!askView, "askId", tointeger(null)),
      version: index(
        local!askView,
        "version",
        tointeger(null)
      ),
      returnCDT: true
    ),
    null
  ),
  local!bUs: if(
    ri!positionTypeID = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
      regionId: index(
        local!askView,
        "regionId",
        tointeger(null)
      ),
      isActive: true,
      columns: { "buId", "regionId", "bu" },
      returnCDT: true()
    ),
    null
  ),
  local!selectedBU: if(
    ri!positionTypeID = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    index(
      local!rotationalASKDetails,
      wherecontains(
        ri!buID,
        local!rotationalASKDetails.buId
      ),
      null
    ),
    null
  ),
  local!totalVersions: if(
    ri!positionTypeID = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3338676"(
      askId: index(local!askView, "askId", tointeger(null)),
      columns: "askId",
      returnCDT: true
    ),
    0
  ),
  local!getnomination: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3851730"(
    askid: tointeger(ri!askID),
    columns: {
      "statusId",
      "createdOn",
      "returnBU",
      "originatingBU"
    },
    nominationId: ri!nominationId
  ).data,
  local!totalVersionCount: length(local!totalVersions),
  local!regioncheck: contains(
    tointeger(
      a!flatten(local!getnomination.statusId)
    ),
    tointeger(9)
  ),
  local!userBU: a!refreshVariable(
    value: union(
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      ),
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      )
    ),
    refreshAlways: true
  ),
  local!ismemberofusergroup: or(
    contains(
      touniformstring(local!userBU),
      tostring(
        index(
          local!getnomination,
          "originatingBU",
          null()
        )
      )
    ),
    contains(
      touniformstring(local!userBU),
      tostring(
        index(local!getnomination, "returnBU", null())
      )
    ),
    a!isNullOrEmpty(local!userBU)
  ),
  if(
    local!ismemberofusergroup,
    if(
      ri!positionTypeID = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
